/**
 * Creates a metadata extractor function for a given set of languages.
 *
 * The returned function derives language-related metadata from a node by:
 * - Resolving the language name from the node.
 * - Parsing node.meta (or an empty string) into a metadata structure.
 * - Extracting the "title" meta value (or returning null if missing).
 * - Looking up a language string literal from the provided languages map.
 * - Collecting meta ranges for highlighted, inserted, and deleted sections.
 * - Collecting foldable section boundaries for collapsed sections.
 *
 * @param {Object<string, string>} languages - Map from language name to a language string literal.
 * @returns {(node: any) => {
 *   languageName: any,
 *   title: (string|null),
 *   languageStringLiteral: string,
 *   highlightedLines: any,
 *   insertedLines: any,
 *   deletedLines: any,
 *   foldedSections: any
 * }} A function that extracts metadata from a node.
 */
const createMetadataExtractor = languages => node => {
  const languageName = getLanguageName(node);
  const meta = parseMeta(node.meta || '');
  const title = getMetaString(meta, 'title')?.value || null;
  const languageStringLiteral = languages[languageName] || '';
  const highlightedLines = getMetaRanges(meta, null);
  const insertedLines = getMetaRanges(meta, 'ins');
  const deletedLines = getMetaRanges(meta, 'del');
  const foldedSections = getMetaRangeBoundaries(meta, 'collapse');

  return {
    languageName,
    title,
    languageStringLiteral,
    highlightedLines,
    insertedLines,
    deletedLines,
    foldedSections,
  };
};

/**
 * Builds an array of segment objects by collecting per-index items from a
 * 2D-like structure in `context.segmentsList` across a normalized range,
 * then passing them to a provided factory function.
 *
 * The `begin` and `end` parameters are normalized: if a value is negative,
 * it is treated as an offset from `context.segmentsList.length`.
 *
 * For each index `i` from `0` to `context.count - 1`, it collects
 * `list[j][i]` for all `j` in the inclusive range `[normalizedBegin, normalizedEnd]`,
 * and calls `create(context.idGenerator.next(), allPrevSegments)`.
 *
 * @param {Object} context
 * @param {Array} context.segmentsList A list where each element is indexable by `i` (i.e., `list[j][i]`).
 * @param {number} context.count Number of segments to create (drives the outer loop).
 * @param {Object} context.idGenerator An object with a `next()` method used to generate an id for each created segment.
 * @param {number} begin Start index for the inclusive range; negative values are offsets from `segmentsList.length`.
 * @param {number} end End index for the inclusive range; negative values are offsets from `segmentsList.length`.
 * @param {Function} create Factory function invoked as `create(id, allPrevSegments)`.
 * @returns {Array} An array of created segments, one per `i` in `[0, context.count)`.
 */
function makeSegments(context, begin, end, create) {
  const list = context.segmentsList;

  const normalizedBegin = begin >= 0 ? begin : list.length + begin;
  const normalizedEnd = end >= 0 ? end : list.length + end;

  const segments = [];

  for (let i = 0; i < context.count; ++i) {
    const allPrevSegments = [];

    for (let j = normalizedBegin; j <= normalizedEnd; ++j) {
      allPrevSegments.push(list[j][i]);
    }

    segments.push(create(context.idGenerator.next(), allPrevSegments));
  }

  return segments;
}

/**
 * Builds attribute objects for a code block based on provided metadata and a code highlighter.
 *
 * Creates:
 * - `codeAttributes` with Prism-compatible language classes and translation disabled.
 * - `preAttributes` optionally containing language string literal, title, and a preview flag for Prism.
 *
 * @param {Object} metadata
 * @param {string} metadata.languageName - Language name used to build the `language-<name>` CSS class.
 * @param {string} [metadata.title] - Optional title to be set as `data-code-title`.
 * @param {string} [metadata.languageStringLiteral] - Optional language string literal to be set as `data-code-language`.
 * @param {Function|Object} codeHighlighter - Highlighter reference; its `name` is used to detect Prism.
 * @returns {{ preAttributes: Object, codeAttributes: Object }} An object containing `preAttributes` and `codeAttributes`.
 */
const createAttributes = (metadata, codeHighlighter) => {
  const { languageName, title, languageStringLiteral } = metadata;

  // Note: While something classless, such as `[data-code-grammar=languageName]`
  // would be nicer to look at, Prism uses the same language-X classes to target
  // nested styles. This is also the HTML5 spec suggestion for higlighting code.
  // By using a class for this plugin, consistence and compliance are ensured.
  const codeAttributes = {
    class: `language-${languageName} notranslate`,
    translate: `no`,
  };
  const preAttributes = {};

  if (languageStringLiteral)
    preAttributes[`data-code-language`] = languageStringLiteral;

  if (title) preAttributes[`data-code-title`] = title;

  if (codeHighlighter.name === 'prism')
    preAttributes[`data-code-preview`] = true;

  return { preAttributes, codeAttributes };
};

/**
 * Recursively fills an encoding "fence" by placing characters onto rails.
 * If there are no remaining characters, returns the current fence.
 *
 * @param {Object} params
 * @param {Array<Array<string>>} params.fence - The current fence structure (array of rails).
 * @param {number} params.currentRail - The index of the rail where the next character will be placed.
 * @param {number} params.direction - The current direction used to determine the next rail.
 * @param {Array<string>} params.chars - The remaining characters to place.
 * @returns {Array<Array<string>>} The updated fence after all characters have been placed.
 */
const fillEncodeFence = ({
  fence,
  currentRail,
  direction,
  chars,
}) => {
  if (chars.length === 0) {
    // All chars have been placed on a fence.
    return fence;
  }

  const railCount = fence.length;

  // Getting the next character to place on a fence.
  const [letter, ...nextChars] = chars;
  const nextDirection = getNextDirection({
    railCount,
    currentRail,
    direction,
  });

  return fillEncodeFence({
    fence: fence.map(addCharToRail(currentRail, letter)),
    currentRail: currentRail + nextDirection,
    direction: nextDirection,
    chars: nextChars,
  });
};
